<!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPACE//AG – Lehrer</title>
<style>
:root{color-scheme:dark;--bg:#05080d;--panel:#0b1119;--line:#1c2b3b;--text:#d8e3ee;--muted:#77889a;--accent:#44d9ff}*{box-sizing:border-box}html,body{margin:0;height:100%;background:var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif;overflow:hidden}#app{height:100%;display:grid;grid-template-columns:minmax(0,1fr) 350px;grid-template-rows:54px minmax(0,1fr)}header{grid-column:1/3;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;padding:0 18px;background:#070c12}.brand{font:700 18px ui-monospace,monospace;letter-spacing:.16em}.brand span{color:var(--accent)}.pill{border:1px solid var(--line);padding:5px 9px;border-radius:5px;color:var(--muted);font:11px ui-monospace,monospace}.pill strong{color:var(--text)}.spacer{flex:1}a.top{font:11px ui-monospace,monospace;color:#9deeff;text-decoration:none;border:1px solid #284052;padding:6px 8px}main{position:relative;min-width:0;min-height:0}canvas{display:block;width:100%;height:100%}.hud{position:absolute;left:12px;bottom:12px;display:flex;gap:8px}.box{padding:8px 10px;background:#07101ad9;border:1px solid var(--line);font:11px ui-monospace,monospace;color:#9eb0c0;max-width:340px}aside{border-left:1px solid var(--line);background:var(--panel);padding:14px;overflow:auto}h3{font:700 11px ui-monospace,monospace;letter-spacing:.15em;color:#7f94a8;margin:5px 0 9px}.card{border:1px solid var(--line);background:#08101a;padding:11px;margin-bottom:10px}.big{width:100%;padding:11px;border:1px solid #34788a;background:#0a1b24;color:#9deeff;font-weight:700;cursor:pointer}.big:hover{background:#0d2631}button{border:1px solid #284052;background:#0b1721;color:#c7d7e5;padding:7px 9px;cursor:pointer}button:hover{border-color:#4a718b}.row{display:flex;gap:7px;margin-top:7px}.row>*{flex:1}input{width:100%;border:1px solid #23384a;background:#060c12;color:#dbe8f3;padding:8px}.hint{font-size:11px;line-height:1.45;color:var(--muted);margin-top:7px}.server{font:11px ui-monospace,monospace;color:#91dbea;word-break:break-all}.team{border-left:3px solid var(--c);padding:8px 9px;margin:7px 0;background:#080f17}.team-head{display:flex;justify-content:space-between;font:12px ui-monospace,monospace}.statusdot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:6px;background:#394957}.statusdot.on{background:#54ef9b;box-shadow:0 0 7px #54ef9b88}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin-top:7px;color:#8294a4;font:10px ui-monospace,monospace}.stats b{color:#d8e3ee}.log{font:10px/1.45 ui-monospace,monospace;color:#8093a6;border-bottom:1px solid #121e2a;padding:4px 0}.empty{color:#64788a;font-size:12px;line-height:1.5}.overlay{position:absolute;inset:0;display:none;align-items:center;justify-content:center;pointer-events:none}.overlay.show{display:flex}.overlay .message{background:#070d14e8;border:1px solid #274052;padding:20px 26px;text-align:center;font:12px/1.7 ui-monospace,monospace;color:#9aabba}.overlay b{display:block;color:#ddecf7;font-size:16px;margin-bottom:6px}.speedrow{display:grid;grid-template-columns:1fr 75px;gap:8px;align-items:center;margin-top:7px}input[type=range]{padding:0}@media(max-width:850px){#app{grid-template-columns:1fr;grid-template-rows:54px minmax(50vh,1fr) 40vh}header{grid-column:1}aside{border-left:0;border-top:1px solid var(--line)}}
</style></head><body><div id="app"><header><div class="brand">SPACE<span>//AG</span></div><div class="pill">TICK <strong id="tick">–</strong></div><div class="pill">STATUS <strong id="status">–</strong></div><div class="pill">SPEED <strong id="speedHead">1.0×</strong></div><div class="pill">GRAV <strong id="gravity">OFF</strong></div><div class="pill">SEED <strong id="seed">–</strong></div><div class="spacer"></div><a class="top" href="team.php" target="_blank">TEAM-EDITOR</a><a class="top" href="admin.php?logout=1">LOGOUT</a></header>
<main id="view"><canvas id="space"></canvas><div id="overlay" class="overlay show"><div class="message"><b>NO UNIVERSE</b>Rechts ein neues Universum erzeugen.</div></div><div class="hud"><div class="box">Mausrad: Zoom · Ziehen: Verschieben · R: Gesamtansicht</div><div class="box" id="hover">Objekt berühren für Details</div></div></main>
<aside><h3>UNIVERSUM</h3><div class="card"><label class="hint">Planeten</label><input id="planetCount" type="number" min="15" max="90" value="44"><button class="big" style="margin-top:8px" onclick="newUniverse()">✦ NEUES UNIVERSUM ERZEUGEN</button><div class="row"><button onclick="setRunning(true)">▶ Start</button><button onclick="setRunning(false)">■ Pause</button><button onclick="stepOnce()">▷ Tick</button></div><div class="row"><button onclick="toggleGravity()">Gravitation an/aus</button></div><div class="hint">Tick-Speed</div><div class="speedrow"><input id="tickSpeed" type="range" min="0" max="6" step="1" value="2"><input id="tickSpeedLabel" value="1.0× · 1.50 s" readonly></div><div class="hint">Bis 5× gut für schnelles Beobachten; 10× ist ein kurzer Testmodus mit höherer Serverlast.</div></div>
<h3>SCHÜLER-EDITOR</h3><div class="card"><div id="studentUrl" class="server">ermittle Adresse…</div><div class="row"><button class="big" onclick="window.open('team.php','_blank')">⌘ EDITOR ÖFFNEN</button></div><div class="hint">Diese URL an die Schüler geben. Es ist keine Installation auf den Schülerrechnern nötig.</div></div>
<h3>TEAMS</h3><div id="teams" class="empty">Noch kein Team verbunden.</div><h3>EVENT LOG</h3><div id="logs"></div></aside></div>
<script>
const SPEEDS=[0.25,0.5,1,2,3,5,10],BASE_TICK=1.5;let speedDragging=false;const CSRF=<?=json_encode($csrf,JSON_UNESCAPED_SLASHES)?>;const $=id=>document.getElementById(id);const tick=$('tick'),status=$('status'),speedHead=$('speedHead'),gravity=$('gravity'),seed=$('seed'),overlay=$('overlay'),teams=$('teams'),logs=$('logs'),planetCount=$('planetCount'),tickSpeed=$('tickSpeed'),tickSpeedLabel=$('tickSpeedLabel'),studentUrl=$('studentUrl');const canvas=$('space'),ctx=canvas.getContext('2d');let state=null,dpr=devicePixelRatio||1,cam={x:7000,y:7000,zoom:.05},fittedSeed=null,drag=false,last={x:0,y:0},mouse={x:0,y:0},serverTickSeconds=null;
function resize(){const r=canvas.getBoundingClientRect();canvas.width=r.width*dpr;canvas.height=r.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}addEventListener('resize',resize);resize();function sx(x){return canvas.clientWidth/2+(x-cam.x)*cam.zoom}function sy(y){return canvas.clientHeight/2+(y-cam.y)*cam.zoom}function colorOf(id){return state?.teams.find(t=>t.id===id)?.color||'#68798a'}function fitCamera(){if(!state?.ready)return;const size=state.world_size||14000,pad=80,w=Math.max(200,canvas.clientWidth-pad),h=Math.max(200,canvas.clientHeight-pad);cam.x=size/2;cam.y=size/2;cam.zoom=Math.max(.014,Math.min(1.5,Math.min(w/size,h/size)));draw()}function grid(){const w=canvas.clientWidth,h=canvas.clientHeight;ctx.save();ctx.strokeStyle='#101b27';ctx.lineWidth=1;let step=500*cam.zoom;if(step<35)step*=2;const ox=((w/2-cam.x*cam.zoom)%step+step)%step,oy=((h/2-cam.y*cam.zoom)%step+step)%step;ctx.beginPath();for(let x=ox;x<w;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,h)}for(let y=oy;y<h;y+=step){ctx.moveTo(0,y);ctx.lineTo(w,y)}ctx.stroke();ctx.restore()}
function draw(){ctx.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);grid();if(!state?.ready)return;ctx.strokeStyle='#223245';ctx.strokeRect(sx(0),sy(0),state.world_size*cam.zoom,state.world_size*cam.zoom);for(const p of state.planets){const x=sx(p.x),y=sy(p.y),r=Math.max(3,p.radius*cam.zoom),c=p.owner?colorOf(p.owner):'#526170';ctx.save();ctx.strokeStyle=c;ctx.lineWidth=p.owner?1.8:1;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.32;ctx.setLineDash([2,5]);ctx.beginPath();ctx.arc(x,y,r+5,0,Math.PI*2);ctx.stroke();ctx.restore()}for(const s of state.ships){const x=sx(s.x),y=sy(s.y),c=colorOf(s.team),a=s.heading*Math.PI/180,z=Math.max(5,7*cam.zoom+.5);ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.strokeStyle=c;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(z,0);ctx.lineTo(-z*.7,z*.55);ctx.lineTo(-z*.4,0);ctx.lineTo(-z*.7,-z*.55);ctx.closePath();ctx.stroke();ctx.restore()}updateHover()}
function updateHover(){if(!state?.ready)return;let best=null,bd=14;for(const s of state.ships){const d=Math.hypot(sx(s.x)-mouse.x,sy(s.y)-mouse.y);if(d<bd){bd=d;best={t:'s',o:s}}}for(const p of state.planets){const d=Math.hypot(sx(p.x)-mouse.x,sy(p.y)-mouse.y);if(d<bd){bd=d;best={t:'p',o:p}}}const e=document.getElementById('hover');if(!best){e.textContent='Objekt berühren für Details';return}if(best.t==='s'){const s=best.o;e.innerHTML=`<b style="color:${colorOf(s.team)}">${s.id}</b> · ${esc(s.role)}<br>HP ${Number(s.hp).toFixed(0)} · Schild ${Number(s.shield||0).toFixed(0)} · Fuel ${Number(s.fuel).toFixed(0)} · v ${Number(s.speed).toFixed(1)}`}else{const p=best.o;e.innerHTML=`<b style="color:${p.owner?colorOf(p.owner):'#9aa7b5'}">${esc(p.name)}</b><br>Radius ${Number(p.radius).toFixed(0)} · Fuel ${Number(p.fuel_stock||0).toFixed(0)} (+${p.fuel_rate}/t) · Metal ${Number(p.metal_stock||0).toFixed(0)} (+${p.metal_rate}/t)`}}
canvas.addEventListener('wheel',e=>{e.preventDefault();cam.zoom=Math.max(.014,Math.min(1.5,cam.zoom*(e.deltaY<0?1.15:.87)));draw()},{passive:false});canvas.addEventListener('mousedown',e=>{drag=true;last={x:e.clientX,y:e.clientY}});addEventListener('mouseup',()=>drag=false);addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouse={x:e.clientX-r.left,y:e.clientY-r.top};if(drag){cam.x-=(e.clientX-last.x)/cam.zoom;cam.y-=(e.clientY-last.y)/cam.zoom;last={x:e.clientX,y:e.clientY}}draw()});addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r')fitCamera()});function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(s){state=s;tick.textContent=s.ready?s.tick:'–';status.textContent=!s.ready?'KEIN UNIVERSUM':s.running?'RUNNING':'PAUSED';const secs=Number(s.tick_seconds||BASE_TICK),mult=BASE_TICK/secs;speedHead.textContent=mult.toFixed(mult>=10?0:mult>=2?1:2)+'×';if(!speedDragging){let bi=0,bd=Infinity;SPEEDS.forEach((x,i)=>{const d=Math.abs(x-mult);if(d<bd){bd=d;bi=i}});tickSpeed.value=bi;tickSpeedLabel.value=mult.toFixed(mult>=10?0:mult>=2?1:2)+'× · '+secs.toFixed(2)+' s'}gravity.textContent=s.gravity_enabled?'ON':'OFF';seed.textContent=s.ready?s.seed:'–';overlay.classList.toggle('show',!s.ready);if(s.ready&&fittedSeed!==s.seed){fittedSeed=s.seed;setTimeout(fitCamera,0)}teams.className=s.teams.length?'':'empty';teams.innerHTML=s.teams.length?s.teams.map(t=>`<div class="team" style="--c:${t.color}"><div class="team-head"><span><i class="statusdot ${t.connected?'on':''}"></i><b style="color:${t.color}">${esc(t.name)}</b></span><span>${t.id}</span></div><div class="stats"><span>Ships <b>${t.ships}</b></span><span>Planets <b>${t.planets}</b></span><span>Score <b>${t.score}</b></span><span>Fuel <b>${t.fuel}</b></span><span>Metal <b>${t.metal}</b></span><span>${t.connected?'<b>ONLINE</b>':'offline'}</span></div></div>`).join(''):'Noch kein Team verbunden.';logs.innerHTML=[...s.logs].reverse().map(x=>`<div class="log">${esc(x)}</div>`).join('');draw()}
async function poll(){try{const r=await fetch('api/world.php',{cache:'no-store'});if(r.status===403){location.reload();return}if(r.ok)render(await r.json())}catch(e){}setTimeout(poll,350)}poll();
async function admin(path,body){const r=await fetch('api/admin/'+path+'.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===403){location.reload();throw new Error('Sitzung abgelaufen')}if(!r.ok){const j=await r.json().catch(()=>({detail:'Fehler'}));alert(j.detail||'Fehler');throw new Error(j.detail||'Fehler')}return r.json()}
async function newUniverse(){if(state?.ready&&!confirm('Neues Universum erzeugen? Alle bisherigen Teams, Flotten und gespeicherten Teamcodes werden entfernt.'))return;await admin('universe',{planet_count:parseInt(planetCount.value||'44')})}const setRunning=x=>admin('running',{enabled:x});const stepOnce=()=>admin('step');const toggleGravity=()=>admin('gravity',{enabled:!state?.gravity_enabled});async function setTickSpeed(mult){const seconds=BASE_TICK/mult;const r=await admin('tick_speed',{tick_seconds:seconds});serverTickSeconds=r.tick_seconds}tickSpeed.addEventListener('pointerdown',()=>speedDragging=true);tickSpeed.addEventListener('input',()=>{const mult=SPEEDS[Number(tickSpeed.value)];tickSpeedLabel.value=mult+'× · '+(BASE_TICK/mult).toFixed(2)+' s'});tickSpeed.addEventListener('change',async()=>{const mult=SPEEDS[Number(tickSpeed.value)];await setTickSpeed(mult);speedDragging=false});tickSpeed.addEventListener('pointerup',()=>{speedDragging=false});
fetch('api/server_info.php',{cache:'no-store'}).then(r=>r.json()).then(x=>{studentUrl.textContent=x.student_url;serverTickSeconds=x.tick_seconds;const mult=BASE_TICK/x.tick_seconds;let bi=0,bd=Infinity;SPEEDS.forEach((v,i)=>{const d=Math.abs(v-mult);if(d<bd){bd=d;bi=i}});tickSpeed.value=bi;tickSpeedLabel.value=SPEEDS[bi]+'× · '+(BASE_TICK/SPEEDS[bi]).toFixed(2)+' s'}).catch(()=>{});
</script></body></html>
